CREATE OR REPLACE FUNCTION sync_note_customer_note() RETURNS trigger AS $$
BEGIN
  IF NEW.note IS NOT NULL THEN
    NEW.customer_note := NEW.note;
  ELSIF NEW.note IS NULL AND (NEW.note IS DISTINCT FROM OLD.note) THEN
    NEW.customer_note := NULL;
  END IF;
  IF NEW.customer_note IS NOT NULL THEN
    NEW.note := NEW.customer_note;
  ELSIF NEW.customer_note IS NULL AND (NEW.customer_note IS DISTINCT FROM OLD.customer_note) THEN
    NEW.note := NULL;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
